import type { FullSchema, TableName } from '../db'

type client_script_events = Exclude<keyof FullSchema<'sys_script_client'>['type']['choices'], ''>

type uiType =
    | {
          /** @deprecated User interface to which the client script applies */
          ui_type?: 'desktop' | 'mobile_or_service_portal' | 'all'
          uiType?: never
      }
    | {
          /** User interface to which the client script applies */
          uiType?: 'desktop' | 'mobile_or_service_portal' | 'all'
          ui_type?: never
      }

type appliesExtended =
    | {
          /** @deprecated Indicates whether the client script applies to tables extended from the specified table */
          applies_extended?: boolean
          appliesExtended?: never
      }
    | {
          /** Indicates whether the client script applies to tables extended from the specified table */
          appliesExtended?: boolean
          applies_extended?: never
      }

type isolateScript =
    | {
          /** @deprecated Indicates whether scripts run in strict mode, with access to direct DOM, `jQuery`, `prototype`, and the `window` object turned off */
          isolate_script?: boolean
          isolateScript?: never
      }
    | {
          /** Indicates whether scripts run in strict mode, with access to direct DOM, `jQuery`, `prototype`, and the `window` object turned off */
          isolateScript?: boolean
          isolate_script?: never
      }

/** @interface */
export type ClientScriptProps<
    T extends TableName,
    E extends client_script_events,
    G extends boolean,
> = Now.Internal.WithIdAndMetadata<
    {
        /** Name of the table on which the client script runs */
        table: T
        /**
         * Indicates which views of the table the client script runs.
         * - `true`: the script runs on all views
         * - `false`: the script runs only on specified views
         */
        global?: G
        /**
         * Views of the table on which the client script runs.
         * Only effective when `global` is `false`; ignored otherwise.
         */
        view?: string
        /** Type of client script, which defines when it runs */
        type?: E
        /** Script to be executed when the client script runs */
        script?: string
        /**
         * Field on the table that the client script applies to.
         * Takes effect only when `type` is set to `onChange` or `onCellEdit`; a warning is emitted at build time if set with other event types.
         */
        field?: keyof FullSchema<T> | (string & {})
        /** Name of the client script */
        name: string
        /** The execution order of the client script (lower numbers execute first) */
        order?: number
        /** Whether the record is enabled */
        active?: boolean
        /** Description of the functionality and purpose of the client script */
        description?: string
        /**
         * Strings that are available to the client script as localized messages using `getmessage('[message]')`.
         * @see https://docs.servicenow.com/csh?topicname=t_TranslateAClientScriptMessage.html&version=latest
         */
        messages?: string
    } & Now.Internal.Meta &
        uiType &
        isolateScript &
        appliesExtended
>

/**
 * Creates a Client Script (`sys_script_client`).
 *
 * @see https://docs.servicenow.com/csh?topicname=client-script-api-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **name** - name of the client script
 *   * **table** - name of the table on which the client script runs
 *   * **type** - type of client script, which defines when it runs
 *   * **uiType** - user interface to which the client script applies
 *   * **active**? - whether the record is enabled
 *   * **appliesExtended**? - indicates whether the client script applies to tables extended from the specified table
 *   * **description**? - description of the functionality and purpose of the client script
 *   * **field**? - field on the table that the client script applies to.
 *     This property applies only when the type property is set to `onChange` or `onCellEdit`.
 *   * **global**? - indicates which views of the table the client script runs.
 *     `true`: the script runs on all views
 *     `false`: the script runs only on specified views
 *   * **isolateScript**? - indicates whether scripts run in strict mode, with
 *     access to direct DOM, `jQuery`, `prototype`, and the `window` object turned off
 *   * **messages**? - strings that are available to the client script as localized messages using `getmessage('[message]')`.
 *     For more information, see [Translate a client script message](https://docs.servicenow.com/csh?topicname=t_TranslateAClientScriptMessage.html&version=latest)
 *   * **order**? - the execution order of the client script (lower numbers execute first)
 *   * **script**? - inline script preceded by a `script` tagged template literal.
 *   * **view**? - views of the table on which the client script runs. This
 *     property applies only when the `global` property is set to `false`
 */
export function ClientScript<T extends TableName, E extends client_script_events, G extends boolean = true>(
    properties: ClientScriptProps<T, E, G>
) {
    return properties
}
